insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096003', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960031', '40000000-0000-4000-8000-000000096003', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960032', '40000000-0000-4000-8000-000000096003', 'A composição $f\circ g$ manda primeiro o valor para $g$.', 2), ('60000000-0000-4000-8000-000000960033', '40000000-0000-4000-8000-000000096003', 'Calcule $g(2)$ antes de usar a fórmula de $f$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096003', '$14$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Na composição indicada, a saída de $g$ se torna a entrada de $f$. Trocar a ordem das funções é um erro comum e leva a outro resultado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960031', '40000000-0000-4000-8000-000000096003', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960032', '40000000-0000-4000-8000-000000096003', 'Comece pela função interna', '$g(2)=2^2+1=5$.', 2), ('70000000-0000-4000-8000-000000960033', '40000000-0000-4000-8000-000000096003', 'Use a saída em $f$', '$f(5)=3\cdot5-1$.', 3), ('70000000-0000-4000-8000-000000960034', '40000000-0000-4000-8000-000000096003', 'Conclua', '$15-1=14$, portanto $(f\circ g)(2)=14$.', 4), ('70000000-0000-4000-8000-000000960035', '40000000-0000-4000-8000-000000096003', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096004', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, para qual valor de $a$ a função $f(x)=ax+1$ se $x<2$ e $f(x)=x^2$ se $x\ge2$ é contínua em $x=2$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960041', '40000000-0000-4000-8000-000000096004', 'A', '$a=3$', 1), ('50000000-0000-4000-8000-000000960042', '40000000-0000-4000-8000-000000096004', 'B', '$a=2$', 2), ('50000000-0000-4000-8000-000000960043', '40000000-0000-4000-8000-000000096004', 'C', '$a=1$', 3), ('50000000-0000-4000-8000-000000960044', '40000000-0000-4000-8000-000000096004', 'D', '$a=4$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096004', '50000000-0000-4000-8000-000000960041') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096004', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960041', '40000000-0000-4000-8000-000000096004', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960042', '40000000-0000-4000-8000-000000096004', 'Continuidade exige que limite à esquerda, limite à direita e valor da função coincidam.', 2), ('60000000-0000-4000-8000-000000960043', '40000000-0000-4000-8000-000000096004', 'Em $x=2$, o ramo da direita vale $2^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096004', '$a=3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A função por partes só pode ser contínua na junção quando as duas fórmulas produzem o mesmo valor ali. O ramo que inclui igualdade define também o valor de $f(2)$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960041', '40000000-0000-4000-8000-000000096004', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960042', '40000000-0000-4000-8000-000000096004', 'Avalie o lado direito', 'Como $2\ge2$, $f(2)=2^2=4$.', 2), ('70000000-0000-4000-8000-000000960043', '40000000-0000-4000-8000-000000096004', 'Calcule o limite à esquerda', 'Pelo primeiro ramo, quando $x\to2^-$, o valor tende a $2a+1$.', 3), ('70000000-0000-4000-8000-000000960044', '40000000-0000-4000-8000-000000096004', 'Iguale os valores', 'A continuidade pede $2a+1=4$; portanto $a=3$.', 4), ('70000000-0000-4000-8000-000000960045', '40000000-0000-4000-8000-000000096004', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096005', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e se $x^2+y^2=25$, qual é $dy/dx$ em termos de $x$ e $y$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960051', '40000000-0000-4000-8000-000000096005', 'A', '$-x/y$', 1), ('50000000-0000-4000-8000-000000960052', '40000000-0000-4000-8000-000000096005', 'B', '$x/y$', 2), ('50000000-0000-4000-8000-000000960053', '40000000-0000-4000-8000-000000096005', 'C', '$-y/x$', 3), ('50000000-0000-4000-8000-000000960054', '40000000-0000-4000-8000-000000096005', 'D', '$2x+2y$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
