insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960081', '40000000-0000-4000-8000-000000096008', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960082', '40000000-0000-4000-8000-000000096008', 'Compare os graus do numerador e do denominador.', 2), ('60000000-0000-4000-8000-000000960083', '40000000-0000-4000-8000-000000096008', 'Divida todos os termos por $x^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096008', '$3/2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma razão de polinômios de mesmo grau, os termos de maior grau controlam o comportamento no infinito. Os termos com potências menores desaparecem ao dividir por $x^2$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960081', '40000000-0000-4000-8000-000000096008', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960082', '40000000-0000-4000-8000-000000096008', 'Identifique os graus', 'Numerador e denominador têm grau $2$.', 2), ('70000000-0000-4000-8000-000000960083', '40000000-0000-4000-8000-000000096008', 'Normalize a expressão', 'Dividindo por $x^2$, obtemos $(3-1/x+1/x^2)/(2+5/x^2)$.', 3), ('70000000-0000-4000-8000-000000960084', '40000000-0000-4000-8000-000000096008', 'Passe ao limite', 'Os termos com $1/x$ e $1/x^2$ tendem a zero; sobra $3/2$.', 4), ('70000000-0000-4000-8000-000000960085', '40000000-0000-4000-8000-000000096008', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096009', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Em vez de começar pelas contas, para aproximar uma raiz de $f(x)=x^2-2$ pelo método de Newton, partindo de $x_0=1$, qual é $x_1$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960091', '40000000-0000-4000-8000-000000096009', 'A', '$3/2$', 1), ('50000000-0000-4000-8000-000000960092', '40000000-0000-4000-8000-000000096009', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000960093', '40000000-0000-4000-8000-000000096009', 'C', '$1/2$', 3), ('50000000-0000-4000-8000-000000960094', '40000000-0000-4000-8000-000000096009', 'D', '$\sqrt2$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096009', '50000000-0000-4000-8000-000000960091') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
