insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960111', '40000000-0000-4000-8000-000000096011', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960112', '40000000-0000-4000-8000-000000096011', 'A substituição direta dá uma forma $0/0$; isso pede simplificação.', 2), ('60000000-0000-4000-8000-000000960113', '40000000-0000-4000-8000-000000096011', 'Fatore $x^2-9$ como diferença de quadrados.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096011', '$6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Embora a expressão original não esteja definida em $x=3$, o limite depende dos valores próximos de $3$. Após cancelar o fator que causa o zero no denominador, a tendência fica visível. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960111', '40000000-0000-4000-8000-000000096011', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960112', '40000000-0000-4000-8000-000000096011', 'Fatore o numerador', '$x^2-9=(x-3)(x+3)$.', 2), ('70000000-0000-4000-8000-000000960113', '40000000-0000-4000-8000-000000096011', 'Simplifique perto de $3$', 'Para $x\ne3$, a fração é igual a $x+3$.', 3), ('70000000-0000-4000-8000-000000960114', '40000000-0000-4000-8000-000000096011', 'Avalie a tendência', 'Quando $x$ tende a $3$, $x+3$ tende a $6$.', 4), ('70000000-0000-4000-8000-000000960115', '40000000-0000-4000-8000-000000096011', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096012', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Ao interpretar a situação proposta, um retângulo tem perímetro $20$ e lados $x$ e $10-x$. Para qual $x$ sua área é máxima?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960121', '40000000-0000-4000-8000-000000096012', 'A', '$5$', 1), ('50000000-0000-4000-8000-000000960122', '40000000-0000-4000-8000-000000096012', 'B', '$10$', 2), ('50000000-0000-4000-8000-000000960123', '40000000-0000-4000-8000-000000096012', 'C', '$4$', 3), ('50000000-0000-4000-8000-000000960124', '40000000-0000-4000-8000-000000096012', 'D', '$2,5$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
