insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960131', '40000000-0000-4000-8000-000000096013', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960132', '40000000-0000-4000-8000-000000096013', 'Você pode usar a regra do produto ou expandir antes.', 2), ('60000000-0000-4000-8000-000000960133', '40000000-0000-4000-8000-000000096013', 'Ao expandir, obtenha $x^3+x^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096013', '$3x^2+2x$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em produtos de polinômios simples, expandir pode tornar a derivação transparente. A alternativa que repete apenas parte do produto esquece a contribuição de um fator. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960131', '40000000-0000-4000-8000-000000096013', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960132', '40000000-0000-4000-8000-000000096013', 'Expanda o produto', '$x^2(x+1)=x^3+x^2$.', 2), ('70000000-0000-4000-8000-000000960133', '40000000-0000-4000-8000-000000096013', 'Derive termo a termo', '$(x^3+x^2)''=3x^2+2x$.', 3), ('70000000-0000-4000-8000-000000960134', '40000000-0000-4000-8000-000000096013', 'Escreva o resultado', '$f''(x)=3x^2+2x$.', 4), ('70000000-0000-4000-8000-000000960135', '40000000-0000-4000-8000-000000096013', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096014', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Em vez de começar pelas contas, qual é a derivada de $f(x)=(3x-2)^5$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
