insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960151', '40000000-0000-4000-8000-000000096015', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960152', '40000000-0000-4000-8000-000000096015', 'A substituição dá $0/0$.', 2), ('60000000-0000-4000-8000-000000960153', '40000000-0000-4000-8000-000000096015', 'Pela Regra de l''Hôpital, derive numerador e denominador.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096015', '$1$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A diferença $e^x-1$ é aproximadamente igual a $x$ perto de zero. A Regra de l''Hôpital confirma essa taxa comparando suas derivadas. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960151', '40000000-0000-4000-8000-000000096015', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960152', '40000000-0000-4000-8000-000000096015', 'Verifique a forma', '$e^0-1=0$ e o denominador também é $0$.', 2), ('70000000-0000-4000-8000-000000960153', '40000000-0000-4000-8000-000000096015', 'Derive os dois termos', 'A razão vira $e^x/1$.', 3), ('70000000-0000-4000-8000-000000960154', '40000000-0000-4000-8000-000000096015', 'Avalie no limite', '$e^x$ tende a $e^0=1$.', 4), ('70000000-0000-4000-8000-000000960155', '40000000-0000-4000-8000-000000096015', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
