insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096017', '30000000-0000-4000-8000-000000000012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960171', '40000000-0000-4000-8000-000000096017', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960172', '40000000-0000-4000-8000-000000096017', 'Em uma raiz quadrada real, o radicando não pode ser negativo.', 2), ('60000000-0000-4000-8000-000000960173', '40000000-0000-4000-8000-000000096017', 'Resolva a desigualdade $4-x\ge0$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096017', '$(-\infty,4]$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A raiz quadrada representa um número real apenas quando seu radicando é não negativo. A condição vem da expressão dentro da raiz, e o valor que zera o radicando também é permitido. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960171', '40000000-0000-4000-8000-000000096017', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960172', '40000000-0000-4000-8000-000000096017', 'Observe a restrição', 'Precisamos de $4-x\ge0$ para que $\sqrt{4-x}$ exista nos reais.', 2), ('70000000-0000-4000-8000-000000960173', '40000000-0000-4000-8000-000000096017', 'Isole $x$', 'Somando $x$ aos dois lados, obtemos $4\ge x$, ou $x\le4$.', 3), ('70000000-0000-4000-8000-000000960174', '40000000-0000-4000-8000-000000096017', 'Inclua o extremo', 'Em $x=4$, a raiz vale $0$, que é real. Portanto $4$ pertence ao domínio.', 4), ('70000000-0000-4000-8000-000000960175', '40000000-0000-4000-8000-000000096017', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096018', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, se $f(x)=x^2$, qual é $f''(3)$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
