insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960211', '40000000-0000-4000-8000-000000096021', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960212', '40000000-0000-4000-8000-000000096021', 'Use o limite fundamental $\lim_{u\to0}\sin u/u=1$.', 2), ('60000000-0000-4000-8000-000000960213', '40000000-0000-4000-8000-000000096021', 'Faça aparecer $4x$ também no denominador.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096021', '$4$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O argumento do seno é $4x$, e não apenas $x$. Separar um fator $4$ permite aplicar exatamente o limite fundamental. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960211', '40000000-0000-4000-8000-000000096021', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960212', '40000000-0000-4000-8000-000000096021', 'Reescreva a fração', '$\frac{\sin(4x)}x=4\cdot\frac{\sin(4x)}{4x}$.', 2), ('70000000-0000-4000-8000-000000960213', '40000000-0000-4000-8000-000000096021', 'Aplique o limite fundamental', 'Quando $x\to0$, também $4x\to0$, então a fração tende a $1$.', 3), ('70000000-0000-4000-8000-000000960214', '40000000-0000-4000-8000-000000096021', 'Multiplique o fator externo', 'O limite total é $4\cdot1=4$.', 4), ('70000000-0000-4000-8000-000000960215', '40000000-0000-4000-8000-000000096021', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096022', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, o gráfico de $g(x)=f(x-2)+3$ é obtido a partir do gráfico de $f$. Qual transformação é correta?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960221', '40000000-0000-4000-8000-000000096022', 'A', '2 unidades à direita e 3 para cima', 1), ('50000000-0000-4000-8000-000000960222', '40000000-0000-4000-8000-000000096022', 'B', '2 unidades à esquerda e 3 para cima', 2), ('50000000-0000-4000-8000-000000960223', '40000000-0000-4000-8000-000000096022', 'C', '2 unidades à direita e 3 para baixo', 3), ('50000000-0000-4000-8000-000000960224', '40000000-0000-4000-8000-000000096022', 'D', 'Uma dilatação vertical de fator 3', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096022', '50000000-0000-4000-8000-000000960221') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
