insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960221', '40000000-0000-4000-8000-000000096022', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960222', '40000000-0000-4000-8000-000000096022', 'Alterações dentro do argumento afetam o eixo horizontal.', 2), ('60000000-0000-4000-8000-000000960223', '40000000-0000-4000-8000-000000096022', 'Em $f(x-a)$, o gráfico se desloca na direção oposta ao sinal visível.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096022', '2 unidades à direita e 3 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O termo $x-2$ faz cada valor que antes aparecia em $x$ surgir agora em $x+2$, deslocando o desenho para a direita. O $+3$ externo soma três a cada altura. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960221', '40000000-0000-4000-8000-000000096022', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960222', '40000000-0000-4000-8000-000000096022', 'Leia a transformação horizontal', 'A expressão $f(x-2)$ desloca o gráfico de $f$ em $2$ unidades para a direita.', 2), ('70000000-0000-4000-8000-000000960223', '40000000-0000-4000-8000-000000096022', 'Leia a transformação vertical', 'O termo externo $+3$ acrescenta $3$ a todo valor de saída.', 3), ('70000000-0000-4000-8000-000000960224', '40000000-0000-4000-8000-000000096022', 'Combine os efeitos', 'O resultado é direita $2$ e cima $3$, sem dilatação.', 4), ('70000000-0000-4000-8000-000000960225', '40000000-0000-4000-8000-000000096022', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096023', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, considere $f(x)=x^2$ se $x\ne1$ e $f(1)=k$. Qual valor de k torna f contínua em $x=1$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960231', '40000000-0000-4000-8000-000000096023', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000960232', '40000000-0000-4000-8000-000000096023', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000960233', '40000000-0000-4000-8000-000000096023', 'C', '$0$', 3), ('50000000-0000-4000-8000-000000960234', '40000000-0000-4000-8000-000000096023', 'D', '$5$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
