insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960231', '40000000-0000-4000-8000-000000096023', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960232', '40000000-0000-4000-8000-000000096023', 'Em uma função contínua, o valor no ponto coincide com o limite.', 2), ('60000000-0000-4000-8000-000000960233', '40000000-0000-4000-8000-000000096023', 'Calcule o limite do polinômio quando x se aproxima do ponto.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096023', '$k=1$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A continuidade exige que o valor atribuído no ponto seja igual ao valor para o qual a expressão se aproxima pelas duas direções. Como polinômios são contínuos, basta avaliar a expressão x ao quadrado no ponto indicado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960231', '40000000-0000-4000-8000-000000096023', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960232', '40000000-0000-4000-8000-000000096023', 'Calcule o limite', '$\lim_{x\to1}x^2=1.$', 2), ('70000000-0000-4000-8000-000000960233', '40000000-0000-4000-8000-000000096023', 'Use a continuidade', '$f(1)=\lim_{x\to1}f(x).$', 3), ('70000000-0000-4000-8000-000000960234', '40000000-0000-4000-8000-000000096023', 'Defina k', '$k=1.$', 4), ('70000000-0000-4000-8000-000000960235', '40000000-0000-4000-8000-000000096023', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096024', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, qual é a derivada de $f(x)=\ln(x^3)$ para $x>0$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960241', '40000000-0000-4000-8000-000000096024', 'A', '$3/x$', 1), ('50000000-0000-4000-8000-000000960242', '40000000-0000-4000-8000-000000096024', 'B', '$1/x^3$', 2), ('50000000-0000-4000-8000-000000960243', '40000000-0000-4000-8000-000000096024', 'C', '$3x^2$', 3), ('50000000-0000-4000-8000-000000960244', '40000000-0000-4000-8000-000000096024', 'D', '$\ln(3x^2)$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
