insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960291', '40000000-0000-4000-8000-000000096029', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960292', '40000000-0000-4000-8000-000000096029', 'Compare as aproximações pela esquerda e pela direita.', 2), ('60000000-0000-4000-8000-000000960293', '40000000-0000-4000-8000-000000096029', 'Para $x>0$, $|x|=x$; para $x<0$, $|x|=-x$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096029', 'Não existe.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Um limite bilateral existe apenas quando as tendências pelos dois lados são iguais. Aqui, o módulo altera a fórmula em cada lado de zero. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960291', '40000000-0000-4000-8000-000000096029', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960292', '40000000-0000-4000-8000-000000096029', 'Aproxime pela direita', 'Se $x>0$, $|x|/x=x/x=1$.', 2), ('70000000-0000-4000-8000-000000960293', '40000000-0000-4000-8000-000000096029', 'Aproxime pela esquerda', 'Se $x<0$, $|x|/x=(-x)/x=-1$.', 3), ('70000000-0000-4000-8000-000000960294', '40000000-0000-4000-8000-000000096029', 'Compare os resultados', 'Como $1\ne-1$, os limites laterais diferem e o limite bilateral não existe.', 4), ('70000000-0000-4000-8000-000000960295', '40000000-0000-4000-8000-000000096029', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096030', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Considere cuidadosamente os dados e a soma de dois números positivos é $12$. Quais valores maximizam o produto entre eles?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960301', '40000000-0000-4000-8000-000000096030', 'A', '$6$ e $6$', 1), ('50000000-0000-4000-8000-000000960302', '40000000-0000-4000-8000-000000096030', 'B', '$12$ e $0$', 2), ('50000000-0000-4000-8000-000000960303', '40000000-0000-4000-8000-000000096030', 'C', '$8$ e $4$', 3), ('50000000-0000-4000-8000-000000960304', '40000000-0000-4000-8000-000000096030', 'D', '$10$ e $2$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
