insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960381', '40000000-0000-4000-8000-000000096038', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960382', '40000000-0000-4000-8000-000000096038', 'A derivada mede a inclinação instantânea.', 2), ('60000000-0000-4000-8000-000000960383', '40000000-0000-4000-8000-000000096038', 'Inclinações positivas fazem o gráfico subir da esquerda para a direita.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096038', 'A função é crescente no intervalo.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O sinal positivo da derivada em todos os pontos de um intervalo informa que cada reta tangente aponta para cima quando x aumenta. Isso garante crescimento; não determina, por si só, a existência de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960381', '40000000-0000-4000-8000-000000096038', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960382', '40000000-0000-4000-8000-000000096038', 'Leia o sinal', '$f^{\prime}(x)>0$ no intervalo inteiro.', 2), ('70000000-0000-4000-8000-000000960383', '40000000-0000-4000-8000-000000096038', 'Interprete', 'Inclinação positiva corresponde a aumento dos valores de f.', 3), ('70000000-0000-4000-8000-000000960384', '40000000-0000-4000-8000-000000096038', 'Conclua', 'A função é crescente.', 4), ('70000000-0000-4000-8000-000000960385', '40000000-0000-4000-8000-000000096038', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096039', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Em vez de começar pelas contas, calcule $\lim_{x\to1}\frac{\ln x}{x-1}$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960391', '40000000-0000-4000-8000-000000096039', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000960392', '40000000-0000-4000-8000-000000096039', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000960393', '40000000-0000-4000-8000-000000096039', 'C', '$e$', 3), ('50000000-0000-4000-8000-000000960394', '40000000-0000-4000-8000-000000096039', 'D', 'O limite não existe', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
