insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096039', '30000000-0000-4000-8000-000000000018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960391', '40000000-0000-4000-8000-000000096039', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960392', '40000000-0000-4000-8000-000000096039', 'A expressão tem forma $0/0$.', 2), ('60000000-0000-4000-8000-000000960393', '40000000-0000-4000-8000-000000096039', 'A derivada de $\ln x$ é $1/x$; a Regra de l''Hôpital é aplicável aqui.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096039', '$1$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Perto de $x=1$, $\ln x$ cresce aproximadamente como $x-1$. A Regra de l''Hôpital formaliza essa comparação ao derivar numerador e denominador. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960391', '40000000-0000-4000-8000-000000096039', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960392', '40000000-0000-4000-8000-000000096039', 'Identifique a indeterminação', '$\ln1=0$ e $1-1=0$, portanto temos $0/0$.', 2), ('70000000-0000-4000-8000-000000960393', '40000000-0000-4000-8000-000000096039', 'Derive numerador e denominador', 'A razão passa a ser $(1/x)/1$.', 3), ('70000000-0000-4000-8000-000000960394', '40000000-0000-4000-8000-000000096039', 'Avalie em $1$', '$1/x$ tende a $1$ quando $x$ tende a $1$.', 4), ('70000000-0000-4000-8000-000000960395', '40000000-0000-4000-8000-000000096039', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096040', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Considere cuidadosamente os dados e se $f(x)=2x+1$ e $g(x)=x^2+1$, calcule $(f\circ g)(3)$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960401', '40000000-0000-4000-8000-000000096040', 'A', '$21$', 1), ('50000000-0000-4000-8000-000000960402', '40000000-0000-4000-8000-000000096040', 'B', '$7$', 2), ('50000000-0000-4000-8000-000000960403', '40000000-0000-4000-8000-000000096040', 'C', '$11$', 3), ('50000000-0000-4000-8000-000000960404', '40000000-0000-4000-8000-000000096040', 'D', '$23$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
