insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096042', '$-x/y$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A equação determina pontos de uma circunferência, mas não escreve explicitamente uma única função de x. A derivação implícita preserva essa relação e introduz a taxa desconhecida de y em relação a x. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960421', '40000000-0000-4000-8000-000000096042', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960422', '40000000-0000-4000-8000-000000096042', 'Derive os dois lados', '$2x+2y\\,y^{\\prime}=0$.', 2), ('70000000-0000-4000-8000-000000960423', '40000000-0000-4000-8000-000000096042', 'Isole o termo com a derivada', '$2y\\,y^{\\prime}=-2x$.', 3), ('70000000-0000-4000-8000-000000960424', '40000000-0000-4000-8000-000000096042', 'Divida pelos fatores', '$y^{\\prime}=-x/y$.', 4), ('70000000-0000-4000-8000-000000960425', '40000000-0000-4000-8000-000000096042', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096043', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, a temperatura $T(t)=t^3-6t^2+9t$ tem ponto crítico não nulo em qual instante?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
