insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960431', '40000000-0000-4000-8000-000000096043', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960432', '40000000-0000-4000-8000-000000096043', 'Encontre $T''(t)$ e fatore.', 2), ('60000000-0000-4000-8000-000000960433', '40000000-0000-4000-8000-000000096043', 'Além de $t=0$, procure o outro zero da derivada.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096043', '$t=3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Os instantes críticos são aqueles em que a taxa de variação da temperatura se anula. Fatorar a derivada revela os dois candidatos. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960431', '40000000-0000-4000-8000-000000096043', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960432', '40000000-0000-4000-8000-000000096043', 'Derive', '$T''(t)=3t^2-12t+9$.', 2), ('70000000-0000-4000-8000-000000960433', '40000000-0000-4000-8000-000000096043', 'Fatore', '$T''(t)=3(t^2-4t+3)=3(t-1)(t-3)$.', 3), ('70000000-0000-4000-8000-000000960434', '40000000-0000-4000-8000-000000096043', 'Escolha o crítico pedido', 'Os críticos são $1$ e $3$; o não nulo destacado é $3$.', 4), ('70000000-0000-4000-8000-000000960435', '40000000-0000-4000-8000-000000096043', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096044', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, qual é o domínio real de $f(x)=\ln(x-1)$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
