insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960441', '40000000-0000-4000-8000-000000096044', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960442', '40000000-0000-4000-8000-000000096044', 'O argumento de um logaritmo real deve ser estritamente positivo.', 2), ('60000000-0000-4000-8000-000000960443', '40000000-0000-4000-8000-000000096044', 'Imponha que x menos a seja maior do que zero.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096044', '$(1,\infty)$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural não está definido nos reais para zero ou valores negativos. Por isso, procuramos as entradas que tornam seu argumento positivo e não incluímos o ponto que faria o argumento se anular. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960441', '40000000-0000-4000-8000-000000096044', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960442', '40000000-0000-4000-8000-000000096044', 'Imponha a condição', '$x-1>0.$', 2), ('70000000-0000-4000-8000-000000960443', '40000000-0000-4000-8000-000000096044', 'Isole a variável', '$x>1.$', 3), ('70000000-0000-4000-8000-000000960444', '40000000-0000-4000-8000-000000096044', 'Escreva o domínio', '$(1,\infty).$', 4), ('70000000-0000-4000-8000-000000960445', '40000000-0000-4000-8000-000000096044', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096045', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-6$, partindo de $x_0=3$. Qual é $x_1$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960451', '40000000-0000-4000-8000-000000096045', 'A', '$\frac{15}{6}$', 1), ('50000000-0000-4000-8000-000000960452', '40000000-0000-4000-8000-000000096045', 'B', '$3$', 2), ('50000000-0000-4000-8000-000000960453', '40000000-0000-4000-8000-000000096045', 'C', '$2$', 3), ('50000000-0000-4000-8000-000000960454', '40000000-0000-4000-8000-000000096045', 'D', '$\frac{6}{3}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096045', '50000000-0000-4000-8000-000000960451') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096045', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960451', '40000000-0000-4000-8000-000000096045', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960452', '40000000-0000-4000-8000-000000096045', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000960453', '40000000-0000-4000-8000-000000096045', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096045', '$x_1=\frac{15}{6}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960451', '40000000-0000-4000-8000-000000096045', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960452', '40000000-0000-4000-8000-000000096045', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000960453', '40000000-0000-4000-8000-000000096045', 'Aplique Newton', '$x_1=3-\frac{9-6}{2\cdot 3}.$', 3), ('70000000-0000-4000-8000-000000960454', '40000000-0000-4000-8000-000000096045', 'Simplifique', '$x_1=\frac{15}{6}.$', 4), ('70000000-0000-4000-8000-000000960455', '40000000-0000-4000-8000-000000096045', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096046', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, dois números positivos somam 10. Quais valores maximizam o produto entre eles?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960461', '40000000-0000-4000-8000-000000096046', 'A', '5 e 5', 1), ('50000000-0000-4000-8000-000000960462', '40000000-0000-4000-8000-000000096046', 'B', '9 e 1', 2), ('50000000-0000-4000-8000-000000960463', '40000000-0000-4000-8000-000000096046', 'C', '3 e 7', 3), ('50000000-0000-4000-8000-000000960464', '40000000-0000-4000-8000-000000096046', 'D', '10 e 0', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096046', '50000000-0000-4000-8000-000000960461') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096046', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960461', '40000000-0000-4000-8000-000000096046', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960462', '40000000-0000-4000-8000-000000096046', 'Represente um dos números por x e o outro pela soma menos x.', 2), ('60000000-0000-4000-8000-000000960463', '40000000-0000-4000-8000-000000096046', 'O produto resultante é uma parábola voltada para baixo.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096046', '5 e 5.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Com soma fixa, aumentar demais um fator reduz demais o outro. A função produto é uma parábola com concavidade para baixo, e seu vértice representa o equilíbrio que produz o maior valor possível. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960461', '40000000-0000-4000-8000-000000096046', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960462', '40000000-0000-4000-8000-000000096046', 'Modele o produto', '$P(x)=x(10-x)=10x-x^2$.', 2), ('70000000-0000-4000-8000-000000960463', '40000000-0000-4000-8000-000000096046', 'Encontre o ponto crítico', '$P^{\\prime}(x)=10-2x=0$, então $x=5$.', 3), ('70000000-0000-4000-8000-000000960464', '40000000-0000-4000-8000-000000096046', 'Recupere o outro valor', '10-5=5; como a parábola abre para baixo, esse ponto é máximo.', 4), ('70000000-0000-4000-8000-000000960465', '40000000-0000-4000-8000-000000096046', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096047', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, qual é a derivada de $f(x)=xe^x$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960471', '40000000-0000-4000-8000-000000096047', 'A', '$e^x(x+1)$', 1), ('50000000-0000-4000-8000-000000960472', '40000000-0000-4000-8000-000000096047', 'B', '$xe^x$', 2), ('50000000-0000-4000-8000-000000960473', '40000000-0000-4000-8000-000000096047', 'C', '$e^x$', 3), ('50000000-0000-4000-8000-000000960474', '40000000-0000-4000-8000-000000096047', 'D', '$x^2e^x$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096047', '50000000-0000-4000-8000-000000960471') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096047', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960471', '40000000-0000-4000-8000-000000096047', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960472', '40000000-0000-4000-8000-000000096047', 'É um produto de duas funções que dependem de $x$.', 2), ('60000000-0000-4000-8000-000000960473', '40000000-0000-4000-8000-000000096047', 'Use $u''v+uv''$ e lembre-se de que $(e^x)''=e^x$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096047', '$e^x(x+1)$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Cada fator do produto pode variar. A regra do produto soma as duas maneiras pelas quais o valor total muda: variar $x$ mantendo momentaneamente $e^x$, e variar $e^x$ mantendo momentaneamente $x$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960471', '40000000-0000-4000-8000-000000096047', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960472', '40000000-0000-4000-8000-000000096047', 'Aplique a regra do produto', '$(xe^x)''=1\cdot e^x+xcdot e^x$.', 2), ('70000000-0000-4000-8000-000000960473', '40000000-0000-4000-8000-000000096047', 'Fatore o termo comum', '$e^x+xe^x=e^x(1+x)$.', 3), ('70000000-0000-4000-8000-000000960474', '40000000-0000-4000-8000-000000096047', 'Organize', '$f''(x)=e^x(x+1)$.', 4), ('70000000-0000-4000-8000-000000960475', '40000000-0000-4000-8000-000000096047', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096048', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, qual é a derivada de $f(x)=\sin(x^2)$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960481', '40000000-0000-4000-8000-000000096048', 'A', '$2xcos(x^2)$', 1), ('50000000-0000-4000-8000-000000960482', '40000000-0000-4000-8000-000000096048', 'B', '$\cos(x^2)$', 2), ('50000000-0000-4000-8000-000000960483', '40000000-0000-4000-8000-000000096048', 'C', '$2xsin(x)$', 3), ('50000000-0000-4000-8000-000000960484', '40000000-0000-4000-8000-000000096048', 'D', '$\cos(x)$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
