insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096048', '30000000-0000-4000-8000-000000000025', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960481', '40000000-0000-4000-8000-000000096048', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960482', '40000000-0000-4000-8000-000000096048', 'A derivada externa de seno é cosseno.', 2), ('60000000-0000-4000-8000-000000960483', '40000000-0000-4000-8000-000000096048', 'O argumento $x^2$ também varia com $x$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096048', '$2xcos(x^2)$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O cosseno mantém o mesmo argumento interno. O fator $2x$ vem da taxa de variação desse argumento: $x^2$ não cresce uma unidade para cada unidade de $x$, então a derivada não pode ser apenas $\cos(x^2)$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960481', '40000000-0000-4000-8000-000000096048', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960482', '40000000-0000-4000-8000-000000096048', 'Identifique a composição', 'A função externa é $\sin u$ com $u=x^2$.', 2), ('70000000-0000-4000-8000-000000960483', '40000000-0000-4000-8000-000000096048', 'Derive a parte externa', 'A derivada é $\cos(u)$.', 3), ('70000000-0000-4000-8000-000000960484', '40000000-0000-4000-8000-000000096048', 'Multiplique pela interna', 'Como $u''=2x$, fica $2xcos(x^2)$.', 4), ('70000000-0000-4000-8000-000000960485', '40000000-0000-4000-8000-000000096048', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096049', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, calcule $\lim_{x\to 0}\frac{\sin(2x)}{x}$. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960491', '40000000-0000-4000-8000-000000096049', 'A', '$2$', 1), ('50000000-0000-4000-8000-000000960492', '40000000-0000-4000-8000-000000096049', 'B', '$4$', 2), ('50000000-0000-4000-8000-000000960493', '40000000-0000-4000-8000-000000096049', 'C', '$-2$', 3), ('50000000-0000-4000-8000-000000960494', '40000000-0000-4000-8000-000000096049', 'D', '$5$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
