insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960501', '40000000-0000-4000-8000-000000096050', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960502', '40000000-0000-4000-8000-000000096050', 'Escreva $1/x$ como $x^{-1}$.', 2), ('60000000-0000-4000-8000-000000960503', '40000000-0000-4000-8000-000000096050', 'A regra da potência também vale para expoentes negativos.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096050', '$-1/x^2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A forma de potência revela que o expoente diminui de $-1$ para $-2$. O sinal negativo vem do próprio expoente. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960501', '40000000-0000-4000-8000-000000096050', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960502', '40000000-0000-4000-8000-000000096050', 'Reescreva a função', '$1/x=x^{-1}$.', 2), ('70000000-0000-4000-8000-000000960503', '40000000-0000-4000-8000-000000096050', 'Aplique a regra da potência', '$(x^{-1})''=-1x^{-2}$.', 3), ('70000000-0000-4000-8000-000000960504', '40000000-0000-4000-8000-000000096050', 'Use fração novamente', '$-x^{-2}=-1/x^2$.', 4), ('70000000-0000-4000-8000-000000960505', '40000000-0000-4000-8000-000000096050', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096051', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, qual é o domínio real de $f(x)=\sqrt{9-1x}$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960511', '40000000-0000-4000-8000-000000096051', 'A', '$x\le9$', 1), ('50000000-0000-4000-8000-000000960512', '40000000-0000-4000-8000-000000096051', 'B', '$x<9$', 2), ('50000000-0000-4000-8000-000000960513', '40000000-0000-4000-8000-000000096051', 'C', '$x\ge9$', 3), ('50000000-0000-4000-8000-000000960514', '40000000-0000-4000-8000-000000096051', 'D', 'Todos os reais', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
