insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960561', '40000000-0000-4000-8000-000000096056', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960562', '40000000-0000-4000-8000-000000096056', 'Na composição indicada, a função mais próxima da entrada é aplicada primeiro.', 2), ('60000000-0000-4000-8000-000000960563', '40000000-0000-4000-8000-000000096056', 'Comece encontrando $g(2)$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096056', '$13$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A notação de composição define uma ordem: primeiro avaliamos a função interna e depois entregamos sua saída à função externa. Trocar essa ordem é um erro comum, porque em geral as duas funções não comutam. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960561', '40000000-0000-4000-8000-000000096056', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960562', '40000000-0000-4000-8000-000000096056', 'Aplique a função interna', '$g(2)=2^2+1=5$.', 2), ('70000000-0000-4000-8000-000000960563', '40000000-0000-4000-8000-000000096056', 'Use esse resultado em $f$', '$f(5)=3\cdot5-2$.', 3), ('70000000-0000-4000-8000-000000960564', '40000000-0000-4000-8000-000000096056', 'Conclua', '$(f\circ g)(2)=13$.', 4), ('70000000-0000-4000-8000-000000960565', '40000000-0000-4000-8000-000000096056', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096057', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, considere $f(x)=x^2$ se $x\ne3$ e $f(3)=k$. Qual valor de k torna f contínua em $x=3$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
