insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960601', '40000000-0000-4000-8000-000000096060', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960602', '40000000-0000-4000-8000-000000096060', 'O argumento de um logaritmo real deve ser estritamente positivo.', 2), ('60000000-0000-4000-8000-000000960603', '40000000-0000-4000-8000-000000096060', 'Imponha que x menos a seja maior do que zero.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096060', '$(2,\infty)$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural não está definido nos reais para zero ou valores negativos. Por isso, procuramos as entradas que tornam seu argumento positivo e não incluímos o ponto que faria o argumento se anular. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960601', '40000000-0000-4000-8000-000000096060', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960602', '40000000-0000-4000-8000-000000096060', 'Imponha a condição', '$x-2>0.$', 2), ('70000000-0000-4000-8000-000000960603', '40000000-0000-4000-8000-000000096060', 'Isole a variável', '$x>2.$', 3), ('70000000-0000-4000-8000-000000960604', '40000000-0000-4000-8000-000000096060', 'Escreva o domínio', '$(2,\infty).$', 4), ('70000000-0000-4000-8000-000000960605', '40000000-0000-4000-8000-000000096060', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096061', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Em uma verificação de raciocínio, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-12$, partindo de $x_0=4$. Qual é $x_1$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960611', '40000000-0000-4000-8000-000000096061', 'A', '$\frac{28}{8}$', 1), ('50000000-0000-4000-8000-000000960612', '40000000-0000-4000-8000-000000096061', 'B', '$4$', 2), ('50000000-0000-4000-8000-000000960613', '40000000-0000-4000-8000-000000096061', 'C', '$3$', 3), ('50000000-0000-4000-8000-000000960614', '40000000-0000-4000-8000-000000096061', 'D', '$\frac{12}{4}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096061', '50000000-0000-4000-8000-000000960611') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096061', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960611', '40000000-0000-4000-8000-000000096061', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960612', '40000000-0000-4000-8000-000000096061', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000960613', '40000000-0000-4000-8000-000000096061', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096061', '$x_1=\frac{28}{8}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960611', '40000000-0000-4000-8000-000000096061', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960612', '40000000-0000-4000-8000-000000096061', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000960613', '40000000-0000-4000-8000-000000096061', 'Aplique Newton', '$x_1=4-\frac{16-12}{2\cdot 4}.$', 3), ('70000000-0000-4000-8000-000000960614', '40000000-0000-4000-8000-000000096061', 'Simplifique', '$x_1=\frac{28}{8}.$', 4), ('70000000-0000-4000-8000-000000960615', '40000000-0000-4000-8000-000000096061', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096062', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Ao interpretar a situação proposta, dois números positivos somam 12. Quais valores maximizam o produto entre eles?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960621', '40000000-0000-4000-8000-000000096062', 'A', '6 e 6', 1), ('50000000-0000-4000-8000-000000960622', '40000000-0000-4000-8000-000000096062', 'B', '11 e 1', 2), ('50000000-0000-4000-8000-000000960623', '40000000-0000-4000-8000-000000096062', 'C', '4 e 8', 3), ('50000000-0000-4000-8000-000000960624', '40000000-0000-4000-8000-000000096062', 'D', '12 e 0', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
