insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960661', '40000000-0000-4000-8000-000000096066', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960662', '40000000-0000-4000-8000-000000096066', 'Derive cada parcela independentemente.', 2), ('60000000-0000-4000-8000-000000960663', '40000000-0000-4000-8000-000000096066', 'Uma constante não varia quando a entrada muda.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096066', '$12x^3-2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz o expoente em uma unidade. O termo linear mantém apenas seu coeficiente, enquanto o termo constante desaparece na derivada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960661', '40000000-0000-4000-8000-000000096066', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960662', '40000000-0000-4000-8000-000000096066', 'Derive a potência', '$(3x^4)^{\\prime}=12x^3$.', 2), ('70000000-0000-4000-8000-000000960663', '40000000-0000-4000-8000-000000096066', 'Derive os termos restantes', '$(-2x)^{\\prime}=-2$ e $(5)^{\\prime}=0$.', 3), ('70000000-0000-4000-8000-000000960664', '40000000-0000-4000-8000-000000096066', 'Reúna os termos', '$f^{\\prime}(x)=12x^3-2$.', 4), ('70000000-0000-4000-8000-000000960665', '40000000-0000-4000-8000-000000096066', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096067', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, qual é o domínio real de $f(x)=\sqrt{12-2x}$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
