insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960691', '40000000-0000-4000-8000-000000096069', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960692', '40000000-0000-4000-8000-000000096069', 'Área e lado mudam com o tempo, então diferencie ambos em relação a t.', 2), ('60000000-0000-4000-8000-000000960693', '40000000-0000-4000-8000-000000096069', 'A regra da cadeia conecta a velocidade do lado à velocidade da área.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096069', '$dA/dt=12$ cm²/s.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma taxa relacionada, primeiro derivamos a relação geométrica em relação ao tempo. Só então inserimos os valores do instante observado. Isso preserva a relação entre a velocidade de crescimento do lado e a velocidade de crescimento da área. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960691', '40000000-0000-4000-8000-000000096069', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960692', '40000000-0000-4000-8000-000000096069', 'Derive no tempo', '$\frac{dA}{dt}=2s\frac{ds}{dt}.$', 2), ('70000000-0000-4000-8000-000000960693', '40000000-0000-4000-8000-000000096069', 'Substitua o instante', '$s=3 e \frac{ds}{dt}=2.$', 3), ('70000000-0000-4000-8000-000000960694', '40000000-0000-4000-8000-000000096069', 'Calcule', '$\frac{dA}{dt}=2\cdot3\cdot2=12.$', 4), ('70000000-0000-4000-8000-000000960695', '40000000-0000-4000-8000-000000096069', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096070', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Considere cuidadosamente os dados e se $f^{\prime}(x)>0$ no intervalo $(3,5)$, como f se comporta nele?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
