insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096070', 'A função é crescente no intervalo.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O sinal positivo da derivada em todos os pontos de um intervalo informa que cada reta tangente aponta para cima quando x aumenta. Isso garante crescimento; não determina, por si só, a existência de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960701', '40000000-0000-4000-8000-000000096070', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960702', '40000000-0000-4000-8000-000000096070', 'Leia o sinal', '$f^{\prime}(x)>0$ no intervalo inteiro.', 2), ('70000000-0000-4000-8000-000000960703', '40000000-0000-4000-8000-000000096070', 'Interprete', 'Inclinação positiva corresponde a aumento dos valores de f.', 3), ('70000000-0000-4000-8000-000000960704', '40000000-0000-4000-8000-000000096070', 'Conclua', 'A função é crescente.', 4), ('70000000-0000-4000-8000-000000960705', '40000000-0000-4000-8000-000000096070', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
