insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960751', '40000000-0000-4000-8000-000000096075', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960752', '40000000-0000-4000-8000-000000096075', 'Encontre os pontos em que a derivada se anula.', 2), ('60000000-0000-4000-8000-000000960753', '40000000-0000-4000-8000-000000096075', 'A segunda derivada negativa caracteriza um máximo local.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096075', '$x=-2$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Os pontos críticos localizam candidatos a extremos, mas ainda precisam ser classificados. A segunda derivada informa a concavidade: negativa significa que o gráfico se curva para baixo, que é a característica de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960751', '40000000-0000-4000-8000-000000096075', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960752', '40000000-0000-4000-8000-000000096075', 'Derive', '$f^{\prime}(x)=3(x-2)(x+2).$', 2), ('70000000-0000-4000-8000-000000960753', '40000000-0000-4000-8000-000000096075', 'Encontre candidatos', '$f^{\prime}(x)=0\Rightarrow x=-2 ou x=2.$', 3), ('70000000-0000-4000-8000-000000960754', '40000000-0000-4000-8000-000000096075', 'Classifique', '$f^{\prime\prime}(x)=6x<0$ em $x=-2.$', 4), ('70000000-0000-4000-8000-000000960755', '40000000-0000-4000-8000-000000096075', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096076', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, qual é o domínio real de $f(x)=\ln(x-3)$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
