insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960771', '40000000-0000-4000-8000-000000096077', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960772', '40000000-0000-4000-8000-000000096077', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000960773', '40000000-0000-4000-8000-000000096077', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096077', '$x_1=\frac{45}{10}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960771', '40000000-0000-4000-8000-000000096077', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960772', '40000000-0000-4000-8000-000000096077', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000960773', '40000000-0000-4000-8000-000000096077', 'Aplique Newton', '$x_1=5-\frac{25-20}{2\cdot 5}.$', 3), ('70000000-0000-4000-8000-000000960774', '40000000-0000-4000-8000-000000096077', 'Simplifique', '$x_1=\frac{45}{10}.$', 4), ('70000000-0000-4000-8000-000000960775', '40000000-0000-4000-8000-000000096077', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096078', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, dois números positivos somam 14. Quais valores maximizam o produto entre eles?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960781', '40000000-0000-4000-8000-000000096078', 'A', '7 e 7', 1), ('50000000-0000-4000-8000-000000960782', '40000000-0000-4000-8000-000000096078', 'B', '13 e 1', 2), ('50000000-0000-4000-8000-000000960783', '40000000-0000-4000-8000-000000096078', 'C', '5 e 9', 3), ('50000000-0000-4000-8000-000000960784', '40000000-0000-4000-8000-000000096078', 'D', '14 e 0', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
