insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960801', '40000000-0000-4000-8000-000000096080', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960802', '40000000-0000-4000-8000-000000096080', 'Há uma função externa, a potência, e uma função interna linear.', 2), ('60000000-0000-4000-8000-000000960803', '40000000-0000-4000-8000-000000096080', 'Depois de derivar a potência, multiplique pela derivada da parte interna.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096080', '$9(3x-2)^2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da cadeia mede duas variações: a da potência externa e a da expressão interna. O fator da derivada interna é indispensável, mesmo quando a expressão interna parece simples. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960801', '40000000-0000-4000-8000-000000096080', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960802', '40000000-0000-4000-8000-000000096080', 'Derive a camada externa', 'A derivada de $u^3$ é $3u^2$.', 2), ('70000000-0000-4000-8000-000000960803', '40000000-0000-4000-8000-000000096080', 'Reponha a expressão', 'Isso produz $3(3x-2)^2$.', 3), ('70000000-0000-4000-8000-000000960804', '40000000-0000-4000-8000-000000096080', 'Aplique a cadeia', 'Como $(3x-2)^{\\prime}=3$, resulta $9(3x-2)^2$.', 4), ('70000000-0000-4000-8000-000000960805', '40000000-0000-4000-8000-000000096080', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
