insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960821', '40000000-0000-4000-8000-000000096082', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960822', '40000000-0000-4000-8000-000000096082', 'Derive cada parcela independentemente.', 2), ('60000000-0000-4000-8000-000000960823', '40000000-0000-4000-8000-000000096082', 'Uma constante não varia quando a entrada muda.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096082', '$10x^4+3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz o expoente em uma unidade. O termo linear mantém apenas seu coeficiente, enquanto o termo constante desaparece na derivada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960821', '40000000-0000-4000-8000-000000096082', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960822', '40000000-0000-4000-8000-000000096082', 'Derive a potência', '$(2x^5)^{\\prime}=10x^4$.', 2), ('70000000-0000-4000-8000-000000960823', '40000000-0000-4000-8000-000000096082', 'Derive os termos restantes', '$(3x)^{\\prime}=3$ e $(-1)^{\\prime}=0$.', 3), ('70000000-0000-4000-8000-000000960824', '40000000-0000-4000-8000-000000096082', 'Reúna os termos', '$f^{\\prime}(x)=10x^4+3$.', 4), ('70000000-0000-4000-8000-000000960825', '40000000-0000-4000-8000-000000096082', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096083', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, qual é o domínio real de $f(x)=\sqrt{15-3x}$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960831', '40000000-0000-4000-8000-000000096083', 'A', '$x\le5$', 1), ('50000000-0000-4000-8000-000000960832', '40000000-0000-4000-8000-000000096083', 'B', '$x<5$', 2), ('50000000-0000-4000-8000-000000960833', '40000000-0000-4000-8000-000000096083', 'C', '$x\ge5$', 3), ('50000000-0000-4000-8000-000000960834', '40000000-0000-4000-8000-000000096083', 'D', 'Todos os reais', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096083', '50000000-0000-4000-8000-000000960831') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096083', '30000000-0000-4000-8000-000000000012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960831', '40000000-0000-4000-8000-000000096083', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960832', '40000000-0000-4000-8000-000000096083', 'O radicando de uma raiz quadrada real deve ser não negativo.', 2), ('60000000-0000-4000-8000-000000960833', '40000000-0000-4000-8000-000000096083', 'Resolva a desigualdade $15-3x\ge0$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096083', '$(-\infty,5]$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O domínio reúne as entradas que tornam a expressão real. Em raízes quadradas, o cuidado é incluir o valor que faz o radicando ser zero: a raiz de zero existe e deve pertencer ao domínio. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960831', '40000000-0000-4000-8000-000000096083', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960832', '40000000-0000-4000-8000-000000096083', 'Imponha a condição', 'Exigimos $15-3x\ge0$.', 2), ('70000000-0000-4000-8000-000000960833', '40000000-0000-4000-8000-000000096083', 'Isole a variável', 'Isso equivale a $3x\le15$ e, como $3>0$, a $x\le5$.', 3), ('70000000-0000-4000-8000-000000960834', '40000000-0000-4000-8000-000000096083', 'Inclua o extremo', 'Em $x=5$, o radicando é zero; portanto o extremo é permitido.', 4), ('70000000-0000-4000-8000-000000960835', '40000000-0000-4000-8000-000000096083', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096084', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Em vez de começar pelas contas, qual é a reta tangente a $f(x)=x^2$ em $x=3$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960841', '40000000-0000-4000-8000-000000096084', 'A', '$y=6x-9$', 1), ('50000000-0000-4000-8000-000000960842', '40000000-0000-4000-8000-000000096084', 'B', '$y=3x$', 2), ('50000000-0000-4000-8000-000000960843', '40000000-0000-4000-8000-000000096084', 'C', '$y=6x$', 3), ('50000000-0000-4000-8000-000000960844', '40000000-0000-4000-8000-000000096084', 'D', '$y=x^2+3$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
