insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096084', '30000000-0000-4000-8000-000000000022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960841', '40000000-0000-4000-8000-000000096084', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960842', '40000000-0000-4000-8000-000000096084', 'A inclinação da reta tangente é a derivada no ponto.', 2), ('60000000-0000-4000-8000-000000960843', '40000000-0000-4000-8000-000000096084', 'O ponto de contato é $(3,f(3))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096084', '$y=6x-9$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960841', '40000000-0000-4000-8000-000000096084', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960842', '40000000-0000-4000-8000-000000096084', 'Encontre o ponto', '$f(3)=9$, então o ponto é $(3,9)$.', 2), ('70000000-0000-4000-8000-000000960843', '40000000-0000-4000-8000-000000096084', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(3)=6$.', 3), ('70000000-0000-4000-8000-000000960844', '40000000-0000-4000-8000-000000096084', 'Monte a reta', '$y-9=6(x-3)$, isto é, $y=6x-9$.', 4), ('70000000-0000-4000-8000-000000960845', '40000000-0000-4000-8000-000000096084', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096085', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e a área de um quadrado é $A=s^2$. Quando $s=4$ cm e o lado cresce a 5 cm/s, qual é $dA/dt$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960851', '40000000-0000-4000-8000-000000096085', 'A', '$40$ cm²/s', 1), ('50000000-0000-4000-8000-000000960852', '40000000-0000-4000-8000-000000096085', 'B', '$20$ cm²/s', 2), ('50000000-0000-4000-8000-000000960853', '40000000-0000-4000-8000-000000096085', 'C', '$14$ cm²/s', 3), ('50000000-0000-4000-8000-000000960854', '40000000-0000-4000-8000-000000096085', 'D', '$25$ cm²/s', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
