insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096085', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960851', '40000000-0000-4000-8000-000000096085', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960852', '40000000-0000-4000-8000-000000096085', 'Área e lado mudam com o tempo, então diferencie ambos em relação a t.', 2), ('60000000-0000-4000-8000-000000960853', '40000000-0000-4000-8000-000000096085', 'A regra da cadeia conecta a velocidade do lado à velocidade da área.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096085', '$dA/dt=40$ cm²/s.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma taxa relacionada, primeiro derivamos a relação geométrica em relação ao tempo. Só então inserimos os valores do instante observado. Isso preserva a relação entre a velocidade de crescimento do lado e a velocidade de crescimento da área. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960851', '40000000-0000-4000-8000-000000096085', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960852', '40000000-0000-4000-8000-000000096085', 'Derive no tempo', '$\frac{dA}{dt}=2s\frac{ds}{dt}.$', 2), ('70000000-0000-4000-8000-000000960853', '40000000-0000-4000-8000-000000096085', 'Substitua o instante', '$s=4 e \frac{ds}{dt}=5.$', 3), ('70000000-0000-4000-8000-000000960854', '40000000-0000-4000-8000-000000096085', 'Calcule', '$\frac{dA}{dt}=2\cdot4\cdot5=40.$', 4), ('70000000-0000-4000-8000-000000960855', '40000000-0000-4000-8000-000000096085', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096086', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, se $f^{\prime}(x)>0$ no intervalo $(4,6)$, como f se comporta nele?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960861', '40000000-0000-4000-8000-000000096086', 'A', 'É crescente.', 1), ('50000000-0000-4000-8000-000000960862', '40000000-0000-4000-8000-000000096086', 'B', 'É decrescente.', 2), ('50000000-0000-4000-8000-000000960863', '40000000-0000-4000-8000-000000096086', 'C', 'É constante.', 3), ('50000000-0000-4000-8000-000000960864', '40000000-0000-4000-8000-000000096086', 'D', 'Tem necessariamente máximo.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096086', '50000000-0000-4000-8000-000000960861') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096086', '30000000-0000-4000-8000-000000000030', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960861', '40000000-0000-4000-8000-000000096086', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960862', '40000000-0000-4000-8000-000000096086', 'A derivada mede a inclinação instantânea.', 2), ('60000000-0000-4000-8000-000000960863', '40000000-0000-4000-8000-000000096086', 'Inclinações positivas fazem o gráfico subir da esquerda para a direita.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096086', 'A função é crescente no intervalo.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O sinal positivo da derivada em todos os pontos de um intervalo informa que cada reta tangente aponta para cima quando x aumenta. Isso garante crescimento; não determina, por si só, a existência de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960861', '40000000-0000-4000-8000-000000096086', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960862', '40000000-0000-4000-8000-000000096086', 'Leia o sinal', '$f^{\prime}(x)>0$ no intervalo inteiro.', 2), ('70000000-0000-4000-8000-000000960863', '40000000-0000-4000-8000-000000096086', 'Interprete', 'Inclinação positiva corresponde a aumento dos valores de f.', 3), ('70000000-0000-4000-8000-000000960864', '40000000-0000-4000-8000-000000096086', 'Conclua', 'A função é crescente.', 4), ('70000000-0000-4000-8000-000000960865', '40000000-0000-4000-8000-000000096086', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096087', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, calcule $\lim_{x\to5}\frac{x^2-25}{x-5}$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
