insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960941', '40000000-0000-4000-8000-000000096094', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960942', '40000000-0000-4000-8000-000000096094', 'Represente um dos números por x e o outro pela soma menos x.', 2), ('60000000-0000-4000-8000-000000960943', '40000000-0000-4000-8000-000000096094', 'O produto resultante é uma parábola voltada para baixo.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096094', '8 e 8.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Com soma fixa, aumentar demais um fator reduz demais o outro. A função produto é uma parábola com concavidade para baixo, e seu vértice representa o equilíbrio que produz o maior valor possível. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960941', '40000000-0000-4000-8000-000000096094', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960942', '40000000-0000-4000-8000-000000096094', 'Modele o produto', '$P(x)=x(16-x)=16x-x^2$.', 2), ('70000000-0000-4000-8000-000000960943', '40000000-0000-4000-8000-000000096094', 'Encontre o ponto crítico', '$P^{\\prime}(x)=16-2x=0$, então $x=8$.', 3), ('70000000-0000-4000-8000-000000960944', '40000000-0000-4000-8000-000000096094', 'Recupere o outro valor', '16-8=8; como a parábola abre para baixo, esse ponto é máximo.', 4), ('70000000-0000-4000-8000-000000960945', '40000000-0000-4000-8000-000000096094', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096095', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Considere cuidadosamente os dados e calcule a derivada de $f(x)=x^2(x+4)$. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
