insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960971', '40000000-0000-4000-8000-000000096097', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960972', '40000000-0000-4000-8000-000000096097', 'Ao substituir x igual a zero, aparece a forma indeterminada zero sobre zero.', 2), ('60000000-0000-4000-8000-000000960973', '40000000-0000-4000-8000-000000096097', 'Derive numerador e denominador uma vez.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096097', '$5$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra de L’Hôpital só pode ser usada depois de confirmar uma forma indeterminada adequada. Aqui, seno de zero e zero no denominador produzem zero sobre zero. Derivar os dois lados da fração transforma o limite em uma avaliação direta, pois a nova razão deixa de ser indeterminada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960971', '40000000-0000-4000-8000-000000096097', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960972', '40000000-0000-4000-8000-000000096097', 'Teste a substituição', '$\sin(0)/0=0/0.$', 2), ('70000000-0000-4000-8000-000000960973', '40000000-0000-4000-8000-000000096097', 'Derive numerador e denominador', '$(\sin(5x))^{\prime}=5\cos(5x) e (x)^{\prime}=1.$', 3), ('70000000-0000-4000-8000-000000960974', '40000000-0000-4000-8000-000000096097', 'Avalie o novo limite', '$5\cos(0)=5.$', 4), ('70000000-0000-4000-8000-000000960975', '40000000-0000-4000-8000-000000096097', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096098', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, qual é a derivada de $f(x)=4x^3-5x+2$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000960981', '40000000-0000-4000-8000-000000096098', 'A', '$12x^2-5$', 1), ('50000000-0000-4000-8000-000000960982', '40000000-0000-4000-8000-000000096098', 'B', '$4x^2-5$', 2), ('50000000-0000-4000-8000-000000960983', '40000000-0000-4000-8000-000000096098', 'C', '$12x^32$', 3), ('50000000-0000-4000-8000-000000960984', '40000000-0000-4000-8000-000000096098', 'D', '$12x^2-5+2$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
