insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000960991', '40000000-0000-4000-8000-000000096099', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000960992', '40000000-0000-4000-8000-000000096099', 'O radicando de uma raiz quadrada real deve ser não negativo.', 2), ('60000000-0000-4000-8000-000000960993', '40000000-0000-4000-8000-000000096099', 'Resolva a desigualdade $20-4x\ge0$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096099', '$(-\infty,5]$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O domínio reúne as entradas que tornam a expressão real. Em raízes quadradas, o cuidado é incluir o valor que faz o radicando ser zero: a raiz de zero existe e deve pertencer ao domínio. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000960991', '40000000-0000-4000-8000-000000096099', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000960992', '40000000-0000-4000-8000-000000096099', 'Imponha a condição', 'Exigimos $20-4x\ge0$.', 2), ('70000000-0000-4000-8000-000000960993', '40000000-0000-4000-8000-000000096099', 'Isole a variável', 'Isso equivale a $4x\le20$ e, como $4>0$, a $x\le5$.', 3), ('70000000-0000-4000-8000-000000960994', '40000000-0000-4000-8000-000000096099', 'Inclua o extremo', 'Em $x=5$, o radicando é zero; portanto o extremo é permitido.', 4), ('70000000-0000-4000-8000-000000960995', '40000000-0000-4000-8000-000000096099', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096100', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e qual é a reta tangente a $f(x)=x^2$ em $x=4$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961001', '40000000-0000-4000-8000-000000096100', 'A', '$y=8x-16$', 1), ('50000000-0000-4000-8000-000000961002', '40000000-0000-4000-8000-000000096100', 'B', '$y=4x$', 2), ('50000000-0000-4000-8000-000000961003', '40000000-0000-4000-8000-000000096100', 'C', '$y=8x$', 3), ('50000000-0000-4000-8000-000000961004', '40000000-0000-4000-8000-000000096100', 'D', '$y=x^2+4$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
