insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961001', '40000000-0000-4000-8000-000000096100', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961002', '40000000-0000-4000-8000-000000096100', 'A inclinação da reta tangente é a derivada no ponto.', 2), ('60000000-0000-4000-8000-000000961003', '40000000-0000-4000-8000-000000096100', 'O ponto de contato é $(4,f(4))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096100', '$y=8x-16$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961001', '40000000-0000-4000-8000-000000096100', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961002', '40000000-0000-4000-8000-000000096100', 'Encontre o ponto', '$f(4)=16$, então o ponto é $(4,16)$.', 2), ('70000000-0000-4000-8000-000000961003', '40000000-0000-4000-8000-000000096100', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(4)=8$.', 3), ('70000000-0000-4000-8000-000000961004', '40000000-0000-4000-8000-000000096100', 'Monte a reta', '$y-16=8(x-4)$, isto é, $y=8x-16$.', 4), ('70000000-0000-4000-8000-000000961005', '40000000-0000-4000-8000-000000096100', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096101', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Em uma verificação de raciocínio, a área de um quadrado é $A=s^2$. Quando $s=5$ cm e o lado cresce a 2 cm/s, qual é $dA/dt$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961011', '40000000-0000-4000-8000-000000096101', 'A', '$20$ cm²/s', 1), ('50000000-0000-4000-8000-000000961012', '40000000-0000-4000-8000-000000096101', 'B', '$10$ cm²/s', 2), ('50000000-0000-4000-8000-000000961013', '40000000-0000-4000-8000-000000096101', 'C', '$13$ cm²/s', 3), ('50000000-0000-4000-8000-000000961014', '40000000-0000-4000-8000-000000096101', 'D', '$4$ cm²/s', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096101', '50000000-0000-4000-8000-000000961011') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096101', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961011', '40000000-0000-4000-8000-000000096101', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961012', '40000000-0000-4000-8000-000000096101', 'Área e lado mudam com o tempo, então diferencie ambos em relação a t.', 2), ('60000000-0000-4000-8000-000000961013', '40000000-0000-4000-8000-000000096101', 'A regra da cadeia conecta a velocidade do lado à velocidade da área.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096101', '$dA/dt=20$ cm²/s.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma taxa relacionada, primeiro derivamos a relação geométrica em relação ao tempo. Só então inserimos os valores do instante observado. Isso preserva a relação entre a velocidade de crescimento do lado e a velocidade de crescimento da área. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961011', '40000000-0000-4000-8000-000000096101', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961012', '40000000-0000-4000-8000-000000096101', 'Derive no tempo', '$\frac{dA}{dt}=2s\frac{ds}{dt}.$', 2), ('70000000-0000-4000-8000-000000961013', '40000000-0000-4000-8000-000000096101', 'Substitua o instante', '$s=5 e \frac{ds}{dt}=2.$', 3), ('70000000-0000-4000-8000-000000961014', '40000000-0000-4000-8000-000000096101', 'Calcule', '$\frac{dA}{dt}=2\cdot5\cdot2=20.$', 4), ('70000000-0000-4000-8000-000000961015', '40000000-0000-4000-8000-000000096101', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
