insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961071', '40000000-0000-4000-8000-000000096107', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961072', '40000000-0000-4000-8000-000000096107', 'Encontre os pontos em que a derivada se anula.', 2), ('60000000-0000-4000-8000-000000961073', '40000000-0000-4000-8000-000000096107', 'A segunda derivada negativa caracteriza um máximo local.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096107', '$x=-4$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Os pontos críticos localizam candidatos a extremos, mas ainda precisam ser classificados. A segunda derivada informa a concavidade: negativa significa que o gráfico se curva para baixo, que é a característica de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961071', '40000000-0000-4000-8000-000000096107', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961072', '40000000-0000-4000-8000-000000096107', 'Derive', '$f^{\prime}(x)=3(x-4)(x+4).$', 2), ('70000000-0000-4000-8000-000000961073', '40000000-0000-4000-8000-000000096107', 'Encontre candidatos', '$f^{\prime}(x)=0\Rightarrow x=-4 ou x=4.$', 3), ('70000000-0000-4000-8000-000000961074', '40000000-0000-4000-8000-000000096107', 'Classifique', '$f^{\prime\prime}(x)=6x<0$ em $x=-4.$', 4), ('70000000-0000-4000-8000-000000961075', '40000000-0000-4000-8000-000000096107', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096108', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, qual é o domínio real de $f(x)=\ln(x-5)$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961081', '40000000-0000-4000-8000-000000096108', 'A', '$x>5$', 1), ('50000000-0000-4000-8000-000000961082', '40000000-0000-4000-8000-000000096108', 'B', '$x\ge5$', 2), ('50000000-0000-4000-8000-000000961083', '40000000-0000-4000-8000-000000096108', 'C', '$x<5$', 3), ('50000000-0000-4000-8000-000000961084', '40000000-0000-4000-8000-000000096108', 'D', 'Todos os reais', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
