insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961151', '40000000-0000-4000-8000-000000096115', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961152', '40000000-0000-4000-8000-000000096115', 'O radicando de uma raiz quadrada precisa ser não negativo.', 2), ('60000000-0000-4000-8000-000000961153', '40000000-0000-4000-8000-000000096115', 'Resolva a desigualdade antes de escrever o intervalo.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096115', '$(-\infty,2]$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Uma raiz quadrada real só existe quando a expressão interna é maior ou igual a zero. O ponto em que o radicando zera deve ser incluído, pois a raiz de zero existe. A desigualdade determina todos os valores permitidos de x e o intervalo é a forma mais clara de registrar o domínio. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961151', '40000000-0000-4000-8000-000000096115', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961152', '40000000-0000-4000-8000-000000096115', 'Identifique a informação', 'A raiz quadrada é a única parte que pode restringir x.', 2), ('70000000-0000-4000-8000-000000961153', '40000000-0000-4000-8000-000000096115', 'Escreva a condição', '$2-x\ge0$.', 3), ('70000000-0000-4000-8000-000000961154', '40000000-0000-4000-8000-000000096115', 'Faça o cálculo', '$x\le2$.', 4), ('70000000-0000-4000-8000-000000961155', '40000000-0000-4000-8000-000000096115', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
