insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961161', '40000000-0000-4000-8000-000000096116', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961162', '40000000-0000-4000-8000-000000096116', 'A inclinação da reta tangente é a derivada no ponto.', 2), ('60000000-0000-4000-8000-000000961163', '40000000-0000-4000-8000-000000096116', 'O ponto de contato é $(5,f(5))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096116', '$y=10x-25$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961161', '40000000-0000-4000-8000-000000096116', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961162', '40000000-0000-4000-8000-000000096116', 'Encontre o ponto', '$f(5)=25$, então o ponto é $(5,25)$.', 2), ('70000000-0000-4000-8000-000000961163', '40000000-0000-4000-8000-000000096116', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(5)=10$.', 3), ('70000000-0000-4000-8000-000000961164', '40000000-0000-4000-8000-000000096116', 'Monte a reta', '$y-25=10(x-5)$, isto é, $y=10x-25$.', 4), ('70000000-0000-4000-8000-000000961165', '40000000-0000-4000-8000-000000096116', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096117', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, a área de um quadrado é $A=s^2$. Quando $s=6$ cm e o lado cresce a 4 cm/s, qual é $dA/dt$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961171', '40000000-0000-4000-8000-000000096117', 'A', '$48$ cm²/s', 1), ('50000000-0000-4000-8000-000000961172', '40000000-0000-4000-8000-000000096117', 'B', '$24$ cm²/s', 2), ('50000000-0000-4000-8000-000000961173', '40000000-0000-4000-8000-000000096117', 'C', '$17$ cm²/s', 3), ('50000000-0000-4000-8000-000000961174', '40000000-0000-4000-8000-000000096117', 'D', '$16$ cm²/s', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000096117', '50000000-0000-4000-8000-000000961171') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000096117', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000961171', '40000000-0000-4000-8000-000000096117', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000961172', '40000000-0000-4000-8000-000000096117', 'Área e lado mudam com o tempo, então diferencie ambos em relação a t.', 2), ('60000000-0000-4000-8000-000000961173', '40000000-0000-4000-8000-000000096117', 'A regra da cadeia conecta a velocidade do lado à velocidade da área.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000096117', '$dA/dt=48$ cm²/s.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma taxa relacionada, primeiro derivamos a relação geométrica em relação ao tempo. Só então inserimos os valores do instante observado. Isso preserva a relação entre a velocidade de crescimento do lado e a velocidade de crescimento da área. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000961171', '40000000-0000-4000-8000-000000096117', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000961172', '40000000-0000-4000-8000-000000096117', 'Derive no tempo', '$\frac{dA}{dt}=2s\frac{ds}{dt}.$', 2), ('70000000-0000-4000-8000-000000961173', '40000000-0000-4000-8000-000000096117', 'Substitua o instante', '$s=6 e \frac{ds}{dt}=4.$', 3), ('70000000-0000-4000-8000-000000961174', '40000000-0000-4000-8000-000000096117', 'Calcule', '$\frac{dA}{dt}=2\cdot6\cdot4=48.$', 4), ('70000000-0000-4000-8000-000000961175', '40000000-0000-4000-8000-000000096117', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000096118', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, para $f(x)=x^2-1$, qual ponto pertence ao gráfico e está sobre o eixo x?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000961181', '40000000-0000-4000-8000-000000096118', 'A', '$(1,0)$', 1), ('50000000-0000-4000-8000-000000961182', '40000000-0000-4000-8000-000000096118', 'B', '$(0,1)$', 2), ('50000000-0000-4000-8000-000000961183', '40000000-0000-4000-8000-000000096118', 'C', '$(2,0)$', 3), ('50000000-0000-4000-8000-000000961184', '40000000-0000-4000-8000-000000096118', 'D', '$(0,-1)$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
